import 'dart:io';

import 'package:path/path.dart' as p;

import 'names.dart';
import 'output.dart';
import 'spec.dart';

/// Environment variable that forces the stub on every platform.
const String disableEnvVar = 'HUSK_SDK_DISABLE';

const _header =
    '// GENERATED by husk_sdk from husk.yaml. Do not edit by hand.\n'
    '// Regenerate with: dart run husk_sdk generate';

/// Every file `generate` writes or edits for [spec], in a stable order.
List<PlannedFile> planFiles(HuskSpec spec) => [
  ...?_ios(spec),
  ...?_android(spec),
  OwnedFile(spec.dart.output, dartApi(spec)),
  BlockEdit(
    '.gitignore',
    comment: '#',
    createIfMissing: true,
    body: _ignoreLines(spec),
  ),
  if (File(spec.resolve('.pubignore')).existsSync())
    BlockEdit('.pubignore', comment: '#', body: _ignoreLines(spec)),
];

List<String> _ignoreLines(HuskSpec spec) => [
  '# Vendor binaries copied in by `dart run husk_sdk link`. Never commit or',
  '# publish them.',
  if (spec.ios != null) '/${spec.ios!.dropDir}/',
  if (spec.android != null) '/${spec.android!.dropDir}/',
];

/// Relative paths of the Kotlin sources that differ between linked and stub
/// builds: `(linked, stub)` source directories under the Android module.
const String linkedSourceDir = 'src/husk/linked/kotlin';

/// See [linkedSourceDir].
const String stubSourceDir = 'src/husk/stub/kotlin';

/// The Swift source directory of the shim target.
String shimSourceDir(HuskSpec spec) =>
    '${spec.ios!.packageDir}/Sources/${spec.shim}';

/// The plugin target's Swift source directory.
String pluginSourceDir(HuskSpec spec) =>
    '${spec.ios!.packageDir}/Sources/${spec.ios!.target}';

/// Name of the generated Swift/Kotlin channel type.
String channelType(HuskSpec spec) => '${spec.shim}Channel';

/// The Gradle build file of the Android module, `.kts` when neither exists.
String gradleBuildFile(HuskSpec spec) {
  final dir = spec.android!.moduleDir;
  return ['$dir/build.gradle.kts', '$dir/build.gradle'].firstWhere(
    (f) => File(spec.resolve(f)).existsSync(),
    orElse: () => '$dir/build.gradle.kts',
  );
}

List<PlannedFile>? _ios(HuskSpec spec) {
  final ios = spec.ios;
  if (ios == null) return null;
  final hasManifest = File(spec.resolve(ios.manifest)).existsSync();
  return [
    if (hasManifest || ios.podspec == null)
      BlockEdit(
        ios.manifest,
        comment: '//',
        body: swiftPmBlock(spec),
        requires: (
          RegExp(r'^let package = Package\(', multiLine: true),
          'does not declare `let package = Package(` at the top level, so '
              'the husk_sdk block has nothing to extend',
        ),
      ),
    OwnedFile('${shimSourceDir(spec)}/${spec.shim}.swift', swiftShim(spec)),
    OwnedFile(
      '${pluginSourceDir(spec)}/${channelType(spec)}.swift',
      swiftChannel(spec),
    ),
    if (ios.podspec != null)
      BlockEdit(
        ios.podspec!,
        comment: '#',
        indent: '  ',
        insertAt: InsertAt.beforeLastRubyEnd,
        body: podspecBlock(spec),
        requires: (
          RegExp(r'Pod::Spec\.new\s+do\s+\|s\|'),
          'does not contain `Pod::Spec.new do |s|`; the husk_sdk block '
              'expects the spec variable to be called `s`',
        ),
      ),
  ];
}

/// Lines of the block appended to the plugin's `Package.swift`.
List<String> swiftPmBlock(HuskSpec spec) {
  final ios = spec.ios!;
  final v = 'husk${spec.sdkName}Path';
  return [
    '// Links ${ios.xcframework} when it is found and builds the ${spec.shim}',
    '// stub target otherwise. Looked up in this order:',
    '//   1. \$${spec.envVar}/${ios.xcframework} (absolute, or relative to',
    '//      this directory)',
    '//   2. $dropDirName/${ios.xcframework}, filled by `dart run husk_sdk link`',
    '// $disableEnvVar=1 forces the stub. SwiftPM caches the evaluated manifest',
    '// by its text and the environment, not by the files it looks at: see',
    '// doc/traps.md in husk_sdk when a build does not notice a change.',
    'import Foundation',
    '',
    'let $v: String? = {',
    '    let env = Context.environment',
    '    if let off = env["$disableEnvVar"], !off.isEmpty, off != "0" { return nil }',
    '    let root = URL(fileURLWithPath: Context.packageDirectory).standardizedFileURL',
    '    var candidates: [URL] = []',
    '    if let dir = env["${spec.envVar}"], !dir.isEmpty {',
    '        let base = URL(fileURLWithPath: dir, relativeTo: root)',
    '        candidates.append(base.appendingPathComponent("${ios.xcframework}").standardizedFileURL)',
    '    }',
    '    candidates.append(root.appendingPathComponent("$dropDirName/${ios.xcframework}"))',
    '    let found = candidates.first {',
    '        FileManager.default.fileExists(atPath: \$0.appendingPathComponent("Info.plist").path)',
    '    }',
    '    guard let found else { return nil }',
    '    // binaryTarget paths must be relative to the package root.',
    '    let from = root.pathComponents',
    '    let to = found.pathComponents',
    '    var common = 0',
    '    while common < min(from.count, to.count) && from[common] == to[common] { common += 1 }',
    '    return (Array(repeating: "..", count: from.count - common) + to[common...]).joined(separator: "/")',
    '}()',
    '',
    'package.targets.append(',
    '    .target(',
    '        name: "${spec.shim}",',
    '        dependencies: $v == nil ? [] : [.target(name: "${spec.sdkName}")],',
    '        path: "Sources/${spec.shim}",',
    '        swiftSettings: $v == nil ? [] : [.define("${spec.defineName}")]',
    '    )',
    ')',
    'if let path = $v {',
    '    package.targets.append(.binaryTarget(name: "${spec.sdkName}", path: path))',
    '}',
    'for target in package.targets where target.name == "${ios.target}" {',
    '    target.dependencies.append(.target(name: "${spec.shim}"))',
    '    if $v != nil {',
    '        target.dependencies.append(.target(name: "${spec.sdkName}"))',
    '        target.swiftSettings = (target.swiftSettings ?? []) + [.define("${spec.defineName}")]',
    '    }',
    '}',
  ];
}

/// Lines of the block inserted into the plugin's podspec.
List<String> podspecBlock(HuskSpec spec) {
  final ios = spec.ios!;
  final podDir = p.posix.dirname(ios.podspec!);
  // Paths inside the block are relative to the podspec's directory.
  final pkg = p.posix.relative(ios.packageDir, from: podDir);
  final shimGlob = p.posix.relative(
    '${shimSourceDir(spec)}/**/*.swift',
    from: podDir,
  );
  return [
    '# Links ${ios.xcframework} when $pkg/$dropDirName/ holds it (copied there',
    '# by `dart run husk_sdk link`, which also reads \$${spec.envVar}) and',
    '# compiles the ${spec.shim} stub otherwise. $disableEnvVar=1 forces the',
    '# stub. Run `pod install` after linking or unlinking so CocoaPods re-reads',
    '# this file.',
    "husk_off = !ENV['$disableEnvVar'].to_s.empty? && ENV['$disableEnvVar'] != '0'",
    "husk_sdk = '$pkg/$dropDirName/${ios.xcframework}'",
    "husk_sdk = nil if husk_off || !File.exist?(File.join(File.dirname(File.expand_path(__FILE__)), husk_sdk, 'Info.plist'))",
    "s.source_files = Array(s.attributes_hash['source_files']) + ['$shimGlob']",
    'if husk_sdk',
    '  s.vendored_frameworks = husk_sdk',
    "  s.pod_target_xcconfig = (s.attributes_hash['pod_target_xcconfig'] || {}).merge(",
    "    'SWIFT_ACTIVE_COMPILATION_CONDITIONS' => '\$(inherited) ${spec.defineName}'",
    '  )',
    'end',
  ];
}

/// The shim type compiled into every build, linked or not.
String swiftShim(HuskSpec spec) =>
    '''
$_header

#if ${spec.defineName}
import ${spec.sdkName}
#endif

/// Tells native code whether ${spec.sdkName} was linked into this build.
///
/// SwiftPM builds this file as its own `${spec.shim}` target; CocoaPods
/// compiles it into the plugin pod. Either way `${spec.defineName}` is
/// defined only when the vendor xcframework was found at build time, so
/// guard every use of the vendor API with `#if ${spec.defineName}`.
public enum ${spec.shim} {
    /// Name of the vendor SDK.
    public static let sdkName = "${spec.sdkName}"

#if ${spec.defineName}
    /// True: this build links the vendor SDK.
    public static let isAvailable = true
#else
    /// False: this build compiled the stub.
    public static let isAvailable = false
#endif
}
''';

/// The method channel handler compiled into the plugin target.
String swiftChannel(HuskSpec spec) =>
    '''
$_header

import Flutter
#if canImport(${spec.shim})
import ${spec.shim}
#endif

/// Answers the `${spec.channel}` channel used by the generated Dart class
/// `${spec.dart.className}`.
///
/// Call `${channelType(spec)}.register(with: registrar)` from the plugin's
/// `register(with:)`.
enum ${channelType(spec)} {
    static let name = "${spec.channel}"

    static func register(with registrar: FlutterPluginRegistrar) {
        let channel = FlutterMethodChannel(name: name, binaryMessenger: registrar.messenger())
        channel.setMethodCallHandler { call, result in
            switch call.method {
            case "status":
                result([
                    "available": ${spec.shim}.isAvailable,
                    "platform": "ios",
                    "sdk": ${spec.shim}.sdkName,
                ])
            default:
                result(FlutterMethodNotImplemented)
            }
        }
    }
}
''';

List<PlannedFile>? _android(HuskSpec spec) {
  final android = spec.android;
  if (android == null) return null;
  final pkgPath = android.kotlinPackage.replaceAll('.', '/');
  final module = android.moduleDir;
  final build = gradleBuildFile(spec);
  final kts = build.endsWith('.kts');
  return [
    OwnedFile('$module/husk.gradle', gradleScript(spec)),
    BlockEdit(
      build,
      comment: '//',
      body: [
        '// Links the vendor AAR when present, a stub otherwise; see husk.gradle.',
        kts ? 'apply(from = "husk.gradle")' : "apply from: 'husk.gradle'",
      ],
    ),
    OwnedFile(
      '$module/${android.sourceDir}/$pkgPath/${channelType(spec)}.kt',
      kotlinChannel(spec),
    ),
    for (final linked in [true, false])
      OwnedFile(
        '$module/${linked ? linkedSourceDir : stubSourceDir}/$pkgPath/${spec.shim}.kt',
        kotlinShim(spec, linked: linked),
      ),
  ];
}

/// The Groovy script applied by the plugin's Gradle build file.
String gradleScript(HuskSpec spec) {
  final android = spec.android!;
  final maven = android.maven;
  final b = StringBuffer()
    ..writeln(_header)
    ..writeln('//');
  if (maven == null) {
    final regex = globToRegExpSource(android.aar!);
    b.write('''
// Links the ${spec.sdkName} AAR when one is found and compiles the stub
// ${spec.shim} otherwise. The first of these directories that holds a file
// matching ${android.aar} wins (the highest file name if several match):
//   1. Gradle property ${spec.gradleProperty} (-P or gradle.properties)
//   2. environment variable ${spec.envVar}
//   3. $dropDirName/ next to this file, filled by `dart run husk_sdk link`
// Relative paths in 1 and 2 resolve against the root Gradle project (the
// app's android/ directory). $disableEnvVar=1 forces the stub.

def huskOff = providers.environmentVariable('$disableEnvVar').getOrElse('')
def huskDisabled = !huskOff.isEmpty() && huskOff != '0'
def huskPattern = ~/$regex/
def huskFind = { String dir ->
    if (dir == null || dir.isEmpty()) return null
    File d = rootProject.file(dir)
    if (!d.isDirectory()) return null
    def matches = (d.listFiles() ?: [] as File[]).findAll { it.isFile() && it.name ==~ huskPattern }
    return matches ? matches.sort { it.name }.last() : null
}
def huskAar = null
if (!huskDisabled) {
    huskAar = huskFind(providers.gradleProperty('${spec.gradleProperty}').getOrNull()) ?:
        huskFind(providers.environmentVariable('${spec.envVar}').getOrNull()) ?:
        huskFind(file('$dropDirName').path)
}

android.sourceSets.main.java.srcDir(huskAar ? '$linkedSourceDir' : '$stubSourceDir')
if (huskAar) {
    logger.lifecycle("husk_sdk: linking ${spec.sdkName} from \${huskAar}")
    // A direct files(...) dependency on an AAR breaks the plugin's own AAR
    // task (bundle*Aar), which Flutter runs. A flat directory repository
    // turns it into a module dependency instead. The app resolves this
    // plugin's dependencies, so every project gets the repository.
    def huskRepoDir = huskAar.parentFile
    rootProject.allprojects { p ->
        p.repositories {
            flatDir { dirs huskRepoDir }
        }
    }
    dependencies {
        implementation(name: huskAar.name - ~/\\.aar\$/, ext: 'aar')
    }
} else {
    logger.info('husk_sdk: ${spec.sdkName} AAR not found, building the stub')
}
''');
  } else {
    b.write('''
// Links ${maven.coordinates} when a repository URL is configured and
// compiles the stub ${spec.shim} otherwise. The URL comes from the Gradle
// property ${maven.urlProperty} or the environment variable ${maven.urlEnv}.
// $disableEnvVar=1 forces the stub.

def huskOff = providers.environmentVariable('$disableEnvVar').getOrElse('')
def huskDisabled = !huskOff.isEmpty() && huskOff != '0'
def huskRepo = providers.gradleProperty('${maven.urlProperty}')
    .orElse(providers.environmentVariable('${maven.urlEnv}'))
    .getOrNull()
def huskLinked = !huskDisabled && huskRepo != null && !huskRepo.isEmpty()

android.sourceSets.main.java.srcDir(huskLinked ? '$linkedSourceDir' : '$stubSourceDir')
if (huskLinked) {
    logger.lifecycle("husk_sdk: linking ${maven.coordinates} from \${huskRepo}")
    // The app resolves this plugin's dependencies, so every project needs
    // the repository.
    rootProject.allprojects { p ->
        p.repositories {
            maven {
                url = huskRepo
''');
    final credentials = {
      'username': maven.usernameProperty,
      'password': maven.passwordProperty,
    };
    if (credentials.values.any((v) => v != null)) {
      b.writeln('                credentials {');
      credentials.forEach((key, property) {
        if (property == null) return;
        b.writeln(
          "                    $key = providers.gradleProperty('$property').getOrNull()",
        );
      });
      b.writeln('                }');
    }
    b.write('''
            }
        }
    }
    dependencies {
        implementation '${maven.coordinates}'
    }
} else {
    logger.info('husk_sdk: no repository URL for ${spec.sdkName}, building the stub')
}
''');
  }
  return b.toString();
}

/// The Kotlin method channel handler, in the plugin's main source set.
String kotlinChannel(HuskSpec spec) =>
    '''
$_header

package ${spec.android!.kotlinPackage}

import io.flutter.plugin.common.BinaryMessenger
import io.flutter.plugin.common.MethodChannel

/**
 * Answers the `${spec.channel}` channel used by the generated Dart class
 * `${spec.dart.className}`.
 *
 * Call `${channelType(spec)}.attach(binding.binaryMessenger)` from
 * `onAttachedToEngine` and `detach` from `onDetachedFromEngine`.
 */
internal object ${channelType(spec)} {
    const val NAME = "${spec.channel}"

    fun attach(messenger: BinaryMessenger) {
        MethodChannel(messenger, NAME).setMethodCallHandler { call, result ->
            when (call.method) {
                "status" -> result.success(
                    mapOf(
                        "available" to ${spec.shim}.IS_AVAILABLE,
                        "platform" to "android",
                        "sdk" to ${spec.shim}.SDK_NAME,
                    ),
                )
                else -> result.notImplemented()
            }
        }
    }

    fun detach(messenger: BinaryMessenger) {
        MethodChannel(messenger, NAME).setMethodCallHandler(null)
    }
}
''';

/// The Kotlin shim; one copy per source set, picked by `husk.gradle`.
String kotlinShim(HuskSpec spec, {required bool linked}) {
  final dir = linked ? linkedSourceDir : stubSourceDir;
  final other = linked ? stubSourceDir : linkedSourceDir;
  return '''
$_header

package ${spec.android!.kotlinPackage}

/**
 * Tells native code whether ${spec.sdkName} was linked into this build.
 *
 * husk.gradle compiles `$dir` when ${linked ? 'the vendor AAR was found' : 'no vendor AAR was found'}
 * and `$other` otherwise. Keep code that calls the vendor API in
 * `$linkedSourceDir` with a matching stub in `$stubSourceDir`.
 */
internal object ${spec.shim} {
    const val SDK_NAME = "${spec.sdkName}"
    const val IS_AVAILABLE = $linked
}
''';
}

/// The Dart API that asks the native side over the method channel.
String dartApi(HuskSpec spec) {
  final version = spec.version == null
      ? 'String? expectedVersion = null'
      : "String expectedVersion = '${spec.version}'";
  return '''
$_header

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// Whether the native ${spec.sdkName} was linked into this build.
///
/// Builds made without the vendor binary compile a stub, and this class
/// reports `false` there. Platforms without the native side (web, desktop,
/// widget tests) report `false` too.
abstract final class ${spec.dart.className} {
  /// Name of the native SDK.
  static const String sdkName = '${spec.sdkName}';

  /// Version of ${spec.sdkName} this plugin expects, from husk.yaml.
  static const $version;

  static const MethodChannel _channel = MethodChannel('${spec.channel}');
  static Future<bool>? _available;

  /// Whether ${spec.sdkName} is linked into the running app.
  ///
  /// The answer cannot change while the app runs, so it is cached.
  static Future<bool> isAvailable() => _available ??= _query();

  static Future<bool> _query() async {
    try {
      final status = await _channel.invokeMapMethod<String, Object?>('status');
      return status?['available'] == true;
    } on MissingPluginException {
      return false;
    } on PlatformException {
      _available = null;
      return false;
    }
  }

  /// Forgets the cached answer, for tests that mock the channel.
  @visibleForTesting
  static void resetForTesting() => _available = null;
}
''';
}
